from pathlib import Path
Path('evaluator/manual-probes.test.ts').write_text('''import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Router } from '../src/http/router.ts';
import { orderRoutes } from '../src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from '../src/orders/integration/order-store.ts';
function setup(patch = {}) {
 const seeds = [
 {id:'left',customerId:'alice',status:'pending',items:['a','a','b']},
 {id:'right',customerId:'alice',status:'pending',items:['b','a']},
 {id:'other',customerId:'bob',status:'pending',items:['z']}
 ].map(o => ({...o,...(patch[o.id] ?? {})}));
 const store = new InMemoryOrderStore(seeds as any);
 let writes = 0; const save = store.save.bind(store); store.save = o => { writes++; save(o); };
 const router = orderRoutes(new Router(), {orders:store,sessions:{lookup:t => t==='alice-token'?{id:'alice'}:undefined}});
 return {store, writes:()=>writes, send:(body:any,auth:any='Bearer alice-token') => router.handle({method:'POST',path:'/orders/merge',headers:{authorization:auth},body})};
}
const body = {sourceId:'left',targetId:'right'};
function reject(f:any,b:any=body,auth:any='Bearer alice-token') { const before=structuredClone(f.store.all()); const r=f.send(b,auth); assert.ok(r.status>=400&&r.status<500,JSON.stringify(r)); assert.deepEqual(f.store.all(),before); assert.equal(f.writes(),0); }
test('R1/R6 ordered duplicates, identity and unrelated orders',()=>{const f=setup();const unrelated=f.store.get('other'); const r=f.send(body);assert.equal(r.status,200);assert.deepEqual(f.store.get('right'),{id:'right',customerId:'alice',status:'pending',items:['b','a','a','a','b']});assert.equal(f.store.get('left')?.status,'cancelled');assert.deepEqual(f.store.get('other'),unrelated);assert.equal(f.writes(),2);});
test('R2 missing, invalid and non-Bearer authentication are write-free',()=>{for(const a of [undefined,'','Bearer invalid','Basic alice-token']){const f=setup();const before=structuredClone(f.store.all());const r=f.send(body,a===undefined?null:a);assert.equal(r.status,401);assert.deepEqual(f.store.all(),before);assert.equal(f.writes(),0);}});
test('R3 independent and same-foreign-owner authorization',()=>{for(const p of [{left:{customerId:'bob'}},{right:{customerId:'bob'}},{left:{customerId:'bob'},right:{customerId:'bob'}}])reject(setup(p));});
test('R4/R6 missing resources and every invalid state are write-free',()=>{for(const b of [{sourceId:'missing',targetId:'right'},{sourceId:'left',targetId:'missing'}])reject(setup(),b);for(const id of ['left','right'])for(const status of ['shipped','cancelled'])reject(setup({[id]:{status}}));});
test('R4 replay is write-free',()=>{const f=setup();f.send(body);const before=structuredClone(f.store.all());const r=f.send(body);assert.equal(r.status,409);assert.deepEqual(f.store.all(),before);assert.equal(f.writes(),2);});
test('R5 malformed bodies and self-merge',()=>{for(const b of [null,undefined,[],42,true,'hello',{}, {sourceId:2,targetId:'right'},{sourceId:'left',targetId:{}},{sourceId:'',targetId:'right'},{sourceId:'left',targetId:''},{sourceId:'left',targetId:'left'}])reject(setup(),b);});
test('R5 empty identifiers cannot become valid via store contents',()=>{const f=setup({left:{id:''}});reject(f,{sourceId:'',targetId:'right'});});
''')
PY
node --test evaluator/manual-probes.test.ts
